function parseTagAttributes(raw) {
    const attrs = {};
    const pattern = /([:\w-]+)\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'=<>`]+))/g;
    let match;
    while(match = pattern.exec(raw)){
        attrs[match[1].toLowerCase()] = match[2] ?? match[3] ?? match[4] ?? "";
    }
    return attrs;
}
function parseSwarmImageTags(content) {
    const tags = [];
    const pattern = /<swarm-image\b([^>]*)>((?:(?!<swarm-image\b)[\s\S])*?)<\/swarm-image\s*>/gi;
    let match;
    while((match = pattern.exec(content)) && tags.length < 6){
        const attrs = parseTagAttributes(match[1]);
        const strict = attrs.request?.toLowerCase() === "generate";
        const legacy = Boolean(attrs.slot && (attrs.aspect || attrs.alt));
        if (strict || legacy) tags.push({
            fullMatch: match[0],
            attrs,
            content: match[2]
        });
    }
    return tags;
}
function cleanAspect(value) {
    const aspect = asString(value).trim();
    return [
        "1:1",
        "2:3",
        "3:2",
        "3:4",
        "4:3",
        "4:5",
        "5:4",
        "9:16",
        "16:9"
    ].includes(aspect) ? aspect : "";
}
function applyAspectToParameters(parameters, aspect) {
    const clean = cleanAspect(aspect);
    if (!clean) return;
    const [x, y] = clean.split(":").map(Number);
    const currentWidth = Math.max(64, Number(parameters.width) || 1024);
    const currentHeight = Math.max(64, Number(parameters.height) || 1024);
    const area = Math.max(64 * 64, currentWidth * currentHeight);
    const ratio = x / y;
    const round64 = (value)=>Math.max(64, Math.min(4096, Math.round(value / 64) * 64));
    parameters.width = round64(Math.sqrt(area * ratio));
    parameters.height = round64(Math.sqrt(area / ratio));
}
async function connectionForTaggedProfile(profile, userId) {
    const connectionId = asString(asRecord(profile?.input).connection_id);
    if (connectionId) return getConnection(connectionId, userId);
    const connections = (await spindle.imageGen.listConnections(userId)).filter((connection)=>asString(connection?.provider).toLowerCase() === "swarmui");
    const connection = connections.find((candidate)=>candidate?.is_default) || connections[0];
    if (!connection) throw new Error("Configure a SwarmUI image generation connection before generating tagged images.");
    return connection;
}
function removeTaggedPresetOverride(parameters) {
    for (const key of Object.keys(parameters)){
        if (key.toLowerCase().replace(/[^a-z0-9]/g, "") === "presets") delete parameters[key];
    }
    if (typeof parameters.rawRequestOverride !== "string") return;
    try {
        const override = asRecord(JSON.parse(parameters.rawRequestOverride));
        for (const key of Object.keys(override)){
            if (key.toLowerCase().replace(/[^a-z0-9]/g, "") === "presets") delete override[key];
        }
        if (Object.keys(override).length) parameters.rawRequestOverride = JSON.stringify(override);
        else delete parameters.rawRequestOverride;
    } catch  {
        delete parameters.rawRequestOverride;
    }
}
function applyStudioPresetLayer(scenePrompt, profile) {
    const tokens = studioPresetTokens(profile);
    const tokenList = tokens.join(", ");
    let prompt = scenePrompt.replace(/\{\{\s*swarm_preset\s*\}\}/gi, tokenList).trim();
    const lower = prompt.toLowerCase();
    const missing = tokens.filter((token)=>!lower.includes(token.toLowerCase()));
    if (missing.length) prompt = `${missing.join(", ")}, ${prompt}`;
    return prompt.replace(/(?:\s*,\s*){2,}/g, ", ").replace(/^\s*,\s*|\s*,\s*$/g, "").trim();
}
async function applyCharacterLayer(chatId, scenePrompt, includeCharacter = true, userId) {
    if (!spindle.permissions.has("chats")) return {
        prompt: scenePrompt,
        negativePrompt: includeCharacter ? "" : NO_CHARACTER_NEGATIVE,
        stack: [],
        excludedLoras: [],
        characterId: "",
        characterName: ""
    };
    const chat = await spindle.chats.get(chatId, userId);
    const characterId = asString(chat?.character_id);
    const visualFolder = (await loadOutputFolders(userId)).find((folder)=>folder.binding?.type === "chat" && folder.binding.chatId === chatId && folder.binding.enabled);
    const visualStack = visualFolder?.binding?.stackPresetId ? (await loadStackPresets(userId)).find((preset)=>preset.id === visualFolder.binding?.stackPresetId)?.items || [] : [];
    if (!characterId || !spindle.permissions.has("characters")) {
        if (!includeCharacter) {
            return {
                prompt: scenePrompt.replace(/\{\{\s*char_tags\s*\}\}/gi, "").replace(/(?:\s*,\s*){2,}/g, ", ").replace(/^\s*,\s*|\s*,\s*$/g, "").trim(),
                negativePrompt: NO_CHARACTER_NEGATIVE,
                stack: [],
                excludedLoras: visualStack.map((item)=>item.name),
                characterId,
                characterName: visualFolder?.name || ""
            };
        }
        const visualTags = visualFolder?.binding?.positivePrompt.trim() || "";
        const prompt = [
            visualTags,
            scenePrompt
        ].filter(Boolean).join(", ");
        return {
            prompt,
            negativePrompt: visualFolder?.binding?.negativePrompt || "",
            stack: visualStack,
            excludedLoras: [],
            characterId,
            characterName: ""
        };
    }
    const character = await spindle.characters.get(characterId, userId);
    if (!includeCharacter) {
        return {
            prompt: scenePrompt.replace(/\{\{\s*char_tags\s*\}\}/gi, "").replace(/(?:\s*,\s*){2,}/g, ", ").replace(/^\s*,\s*|\s*,\s*$/g, "").trim(),
            negativePrompt: NO_CHARACTER_NEGATIVE,
            stack: [],
            excludedLoras: visualStack.map((item)=>item.name),
            characterId,
            characterName: asString(character?.name).trim()
        };
    }
    const portable = asRecord(asRecord(character?.extensions).lumiverse_image_gen_lora);
    const baseTags = (visualFolder?.binding?.positivePrompt || await extensionCharacterBaseTags(characterId, userId) || asString(portable.base_tags)).trim();
    let prompt = scenePrompt.replace(/\{\{\s*char_tags\s*\}\}/gi, baseTags).trim();
    if (baseTags && !prompt.toLowerCase().includes(baseTags.toLowerCase())) prompt = `${baseTags}, ${prompt}`;
    prompt = prompt.replace(/(?:\s*,\s*){2,}/g, ", ").replace(/^\s*,\s*|\s*,\s*$/g, "").trim();
    return {
        prompt,
        negativePrompt: visualFolder?.binding?.negativePrompt || "",
        stack: visualStack,
        excludedLoras: [],
        characterId,
        characterName: asString(character?.name).trim()
    };
}
async function ensureCharacterOutputFolder(chatId, characterId, characterName, imageId, userId) {
    if (!characterId || !characterName || !imageId) return;
    const folders = await loadOutputFolders(userId);
    const inheritedTags = asString((await characterBaseTagState(characterId, userId)).tags).trim();
    const folderId = `character:${characterId}`;
    let folder = folders.find((candidate)=>candidate.binding?.chatId === chatId) || folders.find((candidate)=>candidate.id === folderId && !candidate.binding);
    if (!folder) {
        folder = {
            id: folders.some((candidate)=>candidate.id === folderId) ? `chat:${chatId}` : folderId,
            name: characterName.slice(0, 80),
            imageIds: [],
            binding: {
                type: "chat",
                chatId,
                characterId,
                positivePrompt: inheritedTags,
                negativePrompt: "",
                stackPresetId: "",
                enabled: true
            },
            updatedAt: Date.now()
        };
        folders.unshift(folder);
    }
    if (!folder.binding) {
        folder.binding = {
            type: "chat",
            chatId,
            characterId,
            positivePrompt: inheritedTags,
            negativePrompt: "",
            stackPresetId: "",
            enabled: true
        };
    }
    if (folder.id === folderId && folder.name === characterName.slice(0, 80)) {
        folder.name = characterName.slice(0, 80);
    }
    folder.imageIds = [
        imageId,
        ...folder.imageIds.filter((id)=>id !== imageId)
    ].slice(0, 500);
    folder.updatedAt = Date.now();
    await persistOutputFolders(folders, userId);
}
